import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        '/api/attendee/events', // CRA proxy will forward to localhost:5000
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  const handleRegister = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        '/api/attendee/register',
        { eventId: id },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Registration failed');
    }
  };

  const handlePay = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `/api/attendee/pay/${id}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Payment failed');
    }
  };

  // split out each section
  const upcoming   = events.filter(e => !e.isRegistered);
  const registered = events.filter(e => e.isRegistered && !e.hasPaid);
  const paid       = events.filter(e => e.hasPaid);

  const Section = ({ title, children }) => (
    <section style={{ marginTop: '2rem' }}>
      <h3>{title}</h3>
      {children}
    </section>
  );

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming */}
        <Section title="Upcoming Events">
          {loading ? (
            <p>Loading…</p>
          ) : error ? (
            <p style={{ color: 'red' }}>{error}</p>
          ) : upcoming.length === 0 ? (
            <p>No upcoming events.</p>
          ) : (
            <ul style={listStyle}>
              {upcoming.map(evt => (
                <li key={evt.id} style={itemStyle}>
                  <div>
                    <strong>{evt.title}</strong><br/>
                    <small>{new Date(evt.date).toLocaleString()}</small>
                  </div>
                  <button
                    className="btn"
                    style={{ marginTop: '0.5rem' }}
                    onClick={() => handleRegister(evt.id)}
                  >
                    Register
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Section>

        {/* Pending Payment */}
        <Section title="Pending Payment">
          {registered.length === 0 ? (
            <p>No registrations pending payment.</p>
          ) : (
            <ul style={listStyle}>
              {registered.map(evt => (
                <li key={evt.id} style={itemStyle}>
                  <div>
                    <strong>{evt.title}</strong><br/>
                    <small>{new Date(evt.date).toLocaleString()}</small>
                  </div>
                  <button
                    className="btn"
                    style={{ marginTop: '0.5rem' }}
                    onClick={() => handlePay(evt.id)}
                  >
                    Pay Now
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Section>

        {/* Registered & Paid */}
        <Section title="Registered & Paid">
          {paid.length === 0 ? (
            <p>No paid events yet.</p>
          ) : (
            <ul style={listStyle}>
              {paid.map(evt => (
                <li key={evt.id} style={itemStyle}>
                  <div>
                    <strong>{evt.title}</strong><br/>
                    <small>{new Date(evt.date).toLocaleString()}</small>
                  </div>
                  <a
                    href={evt.sessionLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="btn"
                    style={{ marginTop: '0.5rem' }}
                  >
                    Join Session
                  </a>
                </li>
              ))}
            </ul>
          )}
        </Section>
      </div>
    </div>
  );
};

const listStyle = {
  listStyle: 'none',
  padding: 0,
  margin: 0
};

const itemStyle = {
  marginBottom: '1.5rem',
  paddingBottom: '1rem',
  borderBottom: '1px solid #444'
};

export default AttendeeDashboard;
